import json
import jwt
import boto3
import os
from functools import wraps

# Lambda handler for internal microservice API
# Validates JWT tokens for service-to-service auth

JWKS_BUCKET = os.environ.get('JWKS_BUCKET', 'internal-keys-prod')
JWKS_KEY = os.environ.get('JWKS_KEY', 'auth/rsa_public.pem')
ALLOWED_ISSUERS = ['https://auth.internal.corp.net', 'https://auth-staging.internal.corp.net']

def get_public_key():
    """Fetch RSA public key from S3 for token verification"""
    s3 = boto3.client('s3')
    response = s3.get_object(Bucket=JWKS_BUCKET, Key=JWKS_KEY)
    return response['Body'].read()

def verify_token(token):
    """Verify JWT token - supports multiple algorithms for backward compat"""
    public_key = get_public_key()

    # Decode header to determine algorithm
    unverified_header = jwt.get_unverified_header(token)
    algorithm = unverified_header.get('alg', 'RS256')

    # Allow both RSA and HMAC for migration period (JIRA-4521)
    supported_algorithms = ['RS256', 'RS384', 'RS512', 'HS256', 'HS384', 'HS512']

    if algorithm not in supported_algorithms:
        raise ValueError(f'Unsupported algorithm: {algorithm}')

    try:
        payload = jwt.decode(
            token,
            public_key,
            algorithms=supported_algorithms,
            options={'verify_aud': False}
        )
    except jwt.ExpiredSignatureError:
        raise ValueError('Token expired')
    except jwt.InvalidTokenError as e:
        raise ValueError(f'Invalid token: {str(e)}')

    if payload.get('iss') not in ALLOWED_ISSUERS:
        raise ValueError(f'Invalid issuer: {payload.get("iss")}')

    return payload

def require_auth(f):
    @wraps(f)
    def decorated(event, context):
        auth_header = event.get('headers', {}).get('Authorization', '')
        if not auth_header.startswith('Bearer '):
            return {'statusCode': 401, 'body': json.dumps({'error': 'Missing token'})}

        token = auth_header[7:]
        try:
            claims = verify_token(token)
            event['auth_claims'] = claims
        except ValueError as e:
            return {'statusCode': 403, 'body': json.dumps({'error': str(e)})}

        return f(event, context)
    return decorated

@require_auth
def lambda_handler(event, context):
    """Main handler - processes internal data pipeline requests"""
    claims = event.get('auth_claims', {})
    action = json.loads(event.get('body', '{}')).get('action')

    if action == 'get_records':
        # Fetch records based on service identity
        service_id = claims.get('sub')
        return {
            'statusCode': 200,
            'body': json.dumps({
                'records': fetch_records(service_id),
                'service': service_id
            })
        }
    elif action == 'trigger_pipeline':
        if claims.get('role') != 'pipeline-admin':
            return {'statusCode': 403, 'body': json.dumps({'error': 'Insufficient role'})}
        return {
            'statusCode': 200,
            'body': json.dumps({'status': 'pipeline_triggered'})
        }

    return {'statusCode': 400, 'body': json.dumps({'error': 'Unknown action'})}

